#include <iostream>
#include <memory>
#include <string>
#include <utility>

int main()
{
    auto first = std::make_unique<std::string>("Atlas");
    {
        auto second = std::move(first);
        std::cout << std::boolalpha << static_cast<bool>(first) << ' '
                  << static_cast<bool>(second) << '\n';
        std::cout << *second << '\n';
    }
    std::cout << "Owner empty: " << !first << '\n';
}
